```jsx
import { useState } from 'react';

function TemperatureInput({ label, value, onChange }) {
  return <label>{label}<input value={value} onChange={event => onChange(event.target.value)} /></label>;
}

export default function Converter() {
  const [celsius, setCelsius] = useState('');
  const fahrenheit = celsius === '' ? '' : String(Number(celsius) * 9 / 5 + 32);
  return (
    <>
      <TemperatureInput label="Celsius" value={celsius} onChange={setCelsius} />
      <TemperatureInput label="Fahrenheit" value={fahrenheit} onChange={value => setCelsius(String((Number(value) - 32) * 5 / 9))} />
    </>
  );
}
```
The parent owns Celsius as the source value; Fahrenheit is one current-render calculation, not a second timeline.

```jsx
function toggleTodo(id) {
  setTodos(currentTodos =>
    currentTodos.map(todo =>
      todo.id === id
        ? { ...todo, done: !todo.done }
        : todo
    )
  );
}
```
The array and matching todo are new; unrelated todo objects remain shared because their data did not change.

```jsx
function OrderActions({ order, saveOrder, deleteOrder }) {
  return (
    <div>
      <button onClick={saveOrder}>Save</button>
      <button onClick={() => deleteOrder(order.id)}>Delete</button>
    </div>
  );
}
```
Save passes an existing callback. Delete creates a callback that remembers this order ID without deleting during render.

```jsx
useEffect(() => {
  if (query.trim() === '') {
    setResults([]);
    return undefined;
  }

  const controller = new AbortController();
  const params = new URLSearchParams({ q: query });

  fetch(`/api/search?${params}`, { signal: controller.signal })
    .then(response => {
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response.json();
    })
    .then(setResults)
    .catch(error => { if (error.name !== 'AbortError') setError(error.message); });

  return () => controller.abort();
}, [query]);
```
Every query render owns one controller. Cleanup prevents an older request from publishing after a newer query takes over.
